
CREATE TABLE complaints(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),batch_id uuid NOT NULL REFERENCES batches(id),submitted_by uuid REFERENCES users(id),category text NOT NULL,subject text NOT NULL,message text NOT NULL,is_anonymous boolean NOT NULL DEFAULT false,status text NOT NULL DEFAULT 'OPEN' CHECK(status IN ('OPEN','IN_REVIEW','RESOLVED','CLOSED')),assigned_to uuid,resolved_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(batch_id,id),CHECK(is_anonymous=(submitted_by IS NULL)),FOREIGN KEY(batch_id,assigned_to) REFERENCES batch_memberships(batch_id,user_id));
CREATE INDEX complaints_list ON complaints(batch_id,status,created_at DESC,id DESC);
CREATE TABLE complaint_messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),batch_id uuid NOT NULL,complaint_id uuid NOT NULL,author_user_id uuid REFERENCES users(id),author_type text NOT NULL CHECK(author_type IN ('STUDENT','ADMIN','SYSTEM')),message text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(batch_id,complaint_id) REFERENCES complaints(batch_id,id));
CREATE TABLE feedback(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),batch_id uuid NOT NULL REFERENCES batches(id),submitted_by uuid REFERENCES users(id),category text NOT NULL DEFAULT '',message text NOT NULL,is_anonymous boolean NOT NULL DEFAULT false,rating int CHECK(rating BETWEEN 1 AND 5),status text NOT NULL DEFAULT 'NEW' CHECK(status IN ('NEW','REVIEWED','ARCHIVED')),created_at timestamptz NOT NULL DEFAULT now(),CHECK(is_anonymous=(submitted_by IS NULL)));
CREATE TABLE notification_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),batch_id uuid NOT NULL REFERENCES batches(id),entity_id uuid NOT NULL,event_type text NOT NULL,title text NOT NULL,processed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(entity_id,event_type));
CREATE TABLE notifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),batch_id uuid REFERENCES batches(id),event_id uuid REFERENCES notification_events(id),type text NOT NULL,title text NOT NULL,body text NOT NULL DEFAULT '',entity_id uuid,read_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,event_id));
CREATE INDEX notifications_user ON notifications(user_id,created_at DESC,id DESC);
